import { encodeBase64, join, relative, walk } from "../src/deps.js";

const DIST_DIR = new URL("../ui/dist", import.meta.url).pathname;
const OUTPUT_FILE = new URL("../src/ui-assets.js", import.meta.url).pathname;
const TEXT_EXTENSIONS = [
  ".html",
  ".js",
  ".css",
  ".json",
  ".webmanifest",
  ".svg",
  ".txt",
];

function isTextAsset(path) {
  return TEXT_EXTENSIONS.some((extension) => path.endsWith(extension));
}

async function collectAssets() {
  const assets = {};
  for await (const entry of walk(DIST_DIR, { includeDirs: false })) {
    const assetPath = relative(DIST_DIR, entry.path).replaceAll("\\", "/");
    assets[assetPath] = isTextAsset(assetPath)
      ? { text: await Deno.readTextFile(entry.path) }
      : { base64: encodeBase64(await Deno.readFile(entry.path)) };
  }
  return assets;
}

const assets = await collectAssets();
if (!assets["index.html"]) {
  console.error(`No index.html in ${join(DIST_DIR)} - run imp build first`);
  Deno.exit(1);
}

const lines = Object.keys(assets).sort().map((assetPath) =>
  `  ${JSON.stringify(assetPath)}: ${JSON.stringify(assets[assetPath])},`
);

await Deno.writeTextFile(
  OUTPUT_FILE,
  [
    "// Generated by scripts/bundle-ui.js from the imp build in ui/dist - do not edit",
    "export const UI_ASSETS = {",
    ...lines,
    "};",
    "",
  ].join("\n"),
);

console.log(`Bundled ${lines.length} UI assets into src/ui-assets.js`);
